def fix(n, key, old, new):
    c = next(x for x in CH if x["n"] == n)
    if isinstance(c[key], list):
        hits = [i for i, t in enumerate(c[key]) if old in t]
        assert hits, (n, key, old)
        for i in hits:
            c[key][i] = c[key][i].replace(old, new)
    else:
        assert old in c[key], (n, key, old)
        c[key] = c[key].replace(old, new)


